const results = await Promise.all([
  tools.exec_command({"cmd":"entire agent-help","workdir":"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-session-cleanup-safety","yield_time_ms":10000,"max_output_tokens":20000}),
  tools.exec_command({"cmd":"entire status --json","workdir":"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-session-cleanup-safety","yield_time_ms":10000,"max_output_tokens":10000}),
  tools.exec_command({"cmd":"entire graph version","workdir":"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-session-cleanup-safety","yield_time_ms":10000,"max_output_tokens":10000})
]);
for (let i = 0; i < results.length; i++) {
  text(`---RESULT ${i+1}---`);
  text(results[i].output);
}

const results = await Promise.all([
  tools.exec_command({"cmd":"entire agent-help search --json","workdir":"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-session-cleanup-safety","yield_time_ms":10000,"max_output_tokens":12000}),
  tools.exec_command({"cmd":"entire agent-help session --json","workdir":"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-session-cleanup-safety","yield_time_ms":10000,"max_output_tokens":12000}),
  tools.exec_command({"cmd":"git status --short --branch && git log --oneline --decorate -12","workdir":"/Users/muskanpaliwal/Work/open-source/entire/cli/fix-session-cleanup-safety","yield_time_ms":10000,"max_output_tokens":12000})
]);
for (let i = 0; i < results.length; i++) {
  text(`---RESULT ${i+1}---`);
  text(results[i].output);
}

