{
  "command": "entire search",
  "short": "Search checkpoints, commits, and sessions using semantic and keyword matching",
  "long": "Search checkpoints, commits, and sessions using hybrid search (semantic + keyword),\npowered by the Entire search service.\n\nRequires authentication via 'entire login' (GitHub device flow).\n\nBy default, results are scoped to the current repository. Use --all-repos to\nsearch across all accessible repos.\n\nRun without arguments to open an interactive search. Results are\ndisplayed in an interactive table. Use --json for machine-readable output,\nand add --compact for a trimmed per-result shape suited to agents (implies\n--json): id, type, repo, branch, author, date, files touched, score, match\nsnippet, and a truncated title instead of the full prompt (repo hits add\ndescription and checkpoint count). Fetch full detail\nfor a single result with 'entire checkpoint explain \u003cid\u003e', or add --full to\nthat command to pull the checkpoint's entire session transcript. For a\ncheckpoint hit from another GitHub repo, add --repo \u003cowner/name\u003e to\n'entire checkpoint explain' (requires the full checkpoint ID; unrelated to\nthis command's --repo filter below).\n\nCLI queries also support inline filters like author:\u003cname\u003e, date:\u003cweek|month\u003e,\nbranch:\u003cname\u003e, repo:\u003cowner/name\u003e, and repo:* to search all accessible repos.",
  "example": "entire search \"retry backoff\" --json\n  entire search \"retry backoff\" --json --compact\n  entire search \"auth timeout author:alice date:week\"\n  entire search --code \"parseToken\"",
  "repo": "gh/MuskanPaliwal/cli",
  "flags": [
    {
      "name": "all-repos",
      "type": "bool",
      "default": "false",
      "usage": "Search all accessible repos instead of just the current one"
    },
    {
      "name": "author",
      "type": "string",
      "usage": "Filter by author name"
    },
    {
      "name": "branch",
      "type": "string",
      "usage": "Filter by branch name"
    },
    {
      "name": "case-sensitive",
      "type": "bool",
      "default": "false",
      "usage": "Case-sensitive code search (only with --code)"
    },
    {
      "name": "code",
      "type": "bool",
      "default": "false",
      "usage": "Search code content across repositories"
    },
    {
      "name": "compact",
      "type": "bool",
      "default": "false",
      "usage": "Trimmed JSON output for agents: id, repo, files touched, score, match snippet, and a truncated title instead of the full prompt (implies --json)"
    },
    {
      "name": "date",
      "type": "string",
      "usage": "Filter by time period (week or month)"
    },
    {
      "name": "json",
      "type": "bool",
      "default": "false",
      "usage": "Output as JSON"
    },
    {
      "name": "limit",
      "type": "int",
      "default": "10",
      "usage": "Maximum number of results (per page for checkpoint search, total for --code)"
    },
    {
      "name": "page",
      "type": "int",
      "default": "1",
      "usage": "Page number (1-based)"
    },
    {
      "name": "repo",
      "type": "stringSlice",
      "default": "[]",
      "usage": "Filter by repository (gh/owner/repo, et/proj/repo, owner/repo, ULID, or *); repeatable and comma-separated for multiple repos"
    },
    {
      "name": "context",
      "type": "string",
      "usage": "Act as this saved login `name` for this command only, instead of the active context (entire auth contexts lists them)"
    }
  ]
}

