	newBaseCommit, baseChanged := remapRewriteSHA(state.BaseCommit, rewrites)
	newAttrBaseCommit, attrChanged := remapRewriteSHA(state.AttributionBaseCommit, rewrites)
	if !baseChanged && !attrChanged {
